    'snoringDetectionPurpose': 'क्यों: खर्राटे नींद की गुणवत्ता और इस तरह अगले दिन धूम्रपान के जोखिम को प्रभावित कर सकते हैं। इस सुविधा के लिए पहले नींद बुद्धिमत्ता चालू होनी चाहिए, क्योंकि यह उसी रात के चक्र का उपयोग करती है।',
