    'snoringDetectionDescription': 'ఆన్ చేసినప్పుడు, మీ నిద్ర సమయంలో కొన్ని సెకన్ల ఆడియో నమూనా తీసుకుని పరికరంలో గురక వంటి లయబద్ధమైన శబ్ద నమూనా కోసం విశ్లేషించబడుతుంది. రికార్డింగ్ ఎప్పుడూ డిస్క్‌కు రాయబడదు లేదా పంపబడదు -- ఫలితం (అవును/కాదు) మాత్రమే నిల్వ చేయబడుతుంది.',
    'snoringDetectionPurpose': 'ఎందుకు: గురక నిద్ర నాణ్యతను మరియు తద్వారా మరుసటి రోజు ధూమపాన ప్రమాదాన్ని ప్రభావితం చేయవచ్చు. ఈ ఫీచర్ కోసం ముందుగా స్లీప్ ఇంటెలిజెన్స్ ఆన్‌లో ఉండాలి, ఎందుకంటే ఇది అదే రాత్రి చక్రాన్ని ఉపయోగిస్తుంది.',
    'snoringDetectionEnabledConfirmation': 'గురక పరీక్ష ఆన్ చేయబడింది.',
    'snoringDetectionDisabledConfirmation': 'గురక పరీక్ష ఆఫ్ చేయబడింది.',
    'snoringDetectionRequiresSleepIntelligence': 'ముందుగా స్లీప్ ఇంటెలిజెన్స్‌ను ఆన్ చేయండి -- గురక పరీక్ష దానిపై పనిచేస్తుంది.',
    'snoringDetectionLastNightCount': 'నిన్న రాత్రి గుర్తించిన గురక వంటి నమూనాలు',
  },
